package com.receiptledger.v1.product;

import java.util.*;

public final class InMemoryProductCatalogStore implements ProductCatalogStore {
 private final Map<String,CatalogProduct> products=new HashMap<>(),byCanonical=new HashMap<>();private final Map<String,String> aliases=new HashMap<>();private final Map<String,Link> links=new HashMap<>();
 public synchronized IdentityResolution confirm(String receiptId,int ordinal,String rawAlias,ProductType type,String canonicalName,long now){if(type==ProductType.UNCLASSIFIED)throw new IllegalArgumentException("UNCLASSIFIED cannot create product");String ck=ProductNameNormalizer.key(canonicalName),ak=ProductNameNormalizer.key(rawAlias);if(ck.isEmpty()||ak.isEmpty())throw new IllegalArgumentException("name");CatalogProduct p=byCanonical.get(ck);if(p!=null&&p.type!=type)throw new IllegalStateException("canonical name already exists with different type");if(p==null){p=new CatalogProduct(UUID.randomUUID().toString(),type,canonicalName,now);products.put(p.id,p);byCanonical.put(p.canonicalKey,p);}String aliasProduct=aliases.get(ak);if(aliasProduct!=null&&!aliasProduct.equals(p.id))throw new IllegalStateException("alias already belongs to another product");aliases.put(ak,p.id);links.put(linkKey(receiptId,ordinal),new Link(p.id,LinkSource.USER_CONFIRMED));return IdentityResolution.linked(p,LinkSource.USER_CONFIRMED);}
 public synchronized IdentityResolution resolveAndLinkExact(String receiptId,int ordinal,String rawAlias){String pid=aliases.get(ProductNameNormalizer.key(rawAlias));if(pid==null)return IdentityResolution.unclassified();CatalogProduct p=products.get(pid);if(p==null)return IdentityResolution.unclassified();links.put(linkKey(receiptId,ordinal),new Link(pid,LinkSource.EXACT_ALIAS));return IdentityResolution.linked(p,LinkSource.EXACT_ALIAS);}
 public synchronized IdentityResolution itemResolution(String receiptId,int ordinal){Link l=links.get(linkKey(receiptId,ordinal));if(l==null)return IdentityResolution.unclassified();CatalogProduct p=products.get(l.productId);return p==null?IdentityResolution.unclassified():IdentityResolution.linked(p,l.source);}
 public synchronized List<CatalogProduct> listProducts(){List<CatalogProduct> out=new ArrayList<>(products.values());out.sort((a,b)->a.canonicalName.compareToIgnoreCase(b.canonicalName));return Collections.unmodifiableList(out);}
 public synchronized void unlinkItem(String receiptId,int ordinal){links.remove(linkKey(receiptId,ordinal));}public synchronized void unlinkReceipt(String receiptId){String prefix=receiptId+"#";links.keySet().removeIf(k->k.startsWith(prefix));}public void close(){}
 private static String linkKey(String r,int o){return r+"#"+o;}private static final class Link{final String productId;final LinkSource source;Link(String p,LinkSource s){productId=p;source=s;}}
}
